"use client";

import Image from "next/image";
import Link from "next/link";
import { ShoppingBag, AlertCircle, HeartMinus } from "lucide-react";
import { Product } from "@/types/wishlist";
import { cn } from "@/lib/utils";

interface WishlistCardProps {
  product: Product;
}

export default function WishlistCard({ product }: WishlistCardProps) {
  const discount = product.originalPrice
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)
    : 0;

  return (
    <article className="group relative flex flex-col gap-4 border-b border-border pb-6 sm:border-none sm:pb-0">
      {/* Image Container */}
      <div className="relative aspect-[3/4] overflow-hidden rounded-3xl bg-background-muted">
        <Link href={`/product/${product.slug}`} className="block h-full w-full">
          <img
            src={product.image}
            alt={product.name}
            className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-105"
          />
        </Link>

        {/* Out of Stock Overlay */}
        {!product.inStock && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/60 backdrop-blur-[2px]">
            <div className="flex items-center gap-2 rounded-full border border-border bg-background px-4 py-2 text-xs font-bold uppercase tracking-wider text-foreground shadow-sm">
              <AlertCircle size={14} />
              Sold Out
            </div>
          </div>
        )}

        {/* Action Buttons: Remove & Discount */}
        <div className="absolute inset-x-3 top-3 flex items-start justify-between">
          <div>
            {discount > 0 && (
              <span className="rounded-full bg-destructive px-3 py-1 text-[10px] font-bold text-destructive-foreground uppercase tracking-tighter">
                {discount}% Off
              </span>
            )}
          </div>
          <button
            className="rounded-full bg-background/80 p-2 text-foreground-subtle backdrop-blur-md transition-all hover:bg-destructive hover:text-destructive-foreground active:scale-90"
            aria-label="Remove from favorites"
          >
            <HeartMinus size={18} />
          </button>
        </div>

        {/* Quick Add (Desktop Hover) */}
        {product.inStock && (
          <div className="absolute inset-x-4 bottom-4 translate-y-2 opacity-0 transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100 hidden sm:block">
            <button className="flex w-full items-center justify-center gap-2 rounded-full bg-foreground py-3 text-xs font-bold text-background transition-transform active:scale-95 shadow-xl">
              <ShoppingBag size={16} />
              Add to Bag
            </button>
          </div>
        )}
      </div>

      {/* Product Content */}
      <div className="flex flex-col gap-2 px-1">
        <div className="flex justify-between items-start gap-4">
          <div className="flex-1 min-w-0">
            <h3 className="text-sm font-semibold text-foreground truncate group-hover:text-foreground-muted transition-colors">
              <Link href={`/product/${product.slug}`}>{product.name}</Link>
            </h3>
            <p className="text-xs text-foreground-subtle mt-0.5">
              {product.category} • {product.color}
            </p>
          </div>
          <div className="text-right shrink-0">
            <p className="text-sm font-bold text-foreground">${product.price}</p>
            {product.originalPrice && (
              <p className="text-[11px] text-foreground-subtle line-through">
                ${product.originalPrice}
              </p>
            )}
          </div>
        </div>

        {/* Mobile Action Button */}
        {product.inStock && (
          <button className="w-full sm:hidden mt-1 rounded-full border border-border bg-foreground py-3 text-xs font-bold text-background transition-colors active:bg-foreground/90">
            Move to Bag
          </button>
        )}
      </div>
    </article>
  );
}